mapper.select:
SELECT tran_no, fintech_use_num, tran_date, inout_type,
       tran_amt, after_balance_amt, printed_content, created_at
FROM account_transactions
WHERE fintech_use_num = #{fintechUseNum}
    AND tran_date >= #{fromDate}
    AND tran_date < #{toDate}

    AND tran_date < #{cursor}

ORDER BY tran_date DESC
LIMIT 10;
